@props(['status'])@php($steps=['DRAFT'=>'Draft','SUBMITTED'=>'Dikirim','VERIFIED'=>'Diverifikasi','APPROVED'=>'Disetujui'])<ol class="approval-stepper" aria-label="Tahapan persetujuan">@foreach($steps as $key=>$label)<li class="{{ array_search($key,array_keys($steps))<=array_search($status,array_keys($steps))?'step-complete':'' }}" @if($status===$key) aria-current="step" @endif><span>{{ $loop->iteration }}</span>{{ $label }}</li>@endforeach</ol>@if($status==='RETURNED')<x-badge status="RETURNED">Dikembalikan untuk perbaikan</x-badge>@endif